CREATE OR REPLACE FUNCTION public.research_account_fetch_resume(a uuid, s uuid, e uuid, p_platform text, p_account text, p_refresh uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
